// Cold Waters MP - compares the local DotMod game data with the official DotMod v0.4c release, file by file, so a
// refused connection can name the files that differ. C# 5 / .NET 3.5. Reference: SHA-256 (first 16 hex) per file,
// taken from DotMod.v0.4c.zip (https://github.com/DotModGroup/ColdWaters-DotMod/releases/tag/v0.4c).
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;

namespace ColdWatersMP
{
    public static class DataCheck
    {
        public const string DotModDllSha = "fcbed6e160370ca549aba1752c23948cce21198babff72badb8b6384d367b561";
        static readonly string[] Subs = { "weapons", "vessels", "sensors", "aircraft", "environment" };

        /// <summary>Files under StreamingAssets/dotmod that differ from DotMod v0.4c ("changed x", "missing x", "extra x").</summary>
        public static List<string> Deviations(string dotmodDir)
        {
            List<string> d = new List<string>();
            if (!Directory.Exists(dotmodDir)) return d;
            Dictionary<string, string> refs = new Dictionary<string, string>();
            foreach (string e in Ref.Split('|')) refs[e.Substring(16)] = e.Substring(0, 16);
            HashSet<string> seen = new HashSet<string>();
            List<string> files = new List<string>();
            foreach (string s in Subs)
            {
                string sd = Path.Combine(dotmodDir, s);
                if (Directory.Exists(sd)) files.AddRange(Directory.GetFiles(sd, "*.txt", SearchOption.AllDirectories));
            }
            foreach (string f in new string[] { "config.txt", "subsystems.txt" })
                if (File.Exists(Path.Combine(dotmodDir, f))) files.Add(Path.Combine(dotmodDir, f));
            foreach (string f in files)
            {
                string rel = f.Substring(dotmodDir.Length).TrimStart('\\', '/').Replace('\\', '/').ToLowerInvariant();
                seen.Add(rel);
                string want;
                if (!refs.TryGetValue(rel, out want)) { d.Add("extra " + rel); continue; }
                if (Fingerprint.HashFile(f).Substring(0, 16) != want) d.Add("changed " + rel);
            }
            foreach (string k in refs.Keys) if (!seen.Contains(k)) d.Add("missing " + k);
            d.Sort(System.StringComparer.Ordinal);
            return d;
        }

